#!/data/data/com.termux/files/usr/bin/bash
# ============================================================================
# Velune EQ/IconButton fix — run this FROM INSIDE your existing Velune repo
# checkout (i.e. you've already `cd`'d into it). No cloning/pulling here.
#
# Fixes applied by the embedded patch:
#   1. IconButton onLongClick default-arg fix (original patch)
#   2. EQState UI-state fields (original patch)
#   3. androidx.compose.material3.IconButton -> custom IconButton import swap
#      across 10 screen files (original patch)
#   4. EQViewModel.kt rewritten to match the real EQProfileRepository /
#      SavedEQProfile / ParametricEQBand API (original patch, extended)
#   5. NEW: MusicService.kt was still calling the old static
#      EqualizerService.setProfile()/.setEnabled()/.audioProcessor and
#      EQProfileRepository.getProfile() APIs, none of which exist anymore.
#      Fixed to use the injected Hilt singleton instead.
#   6. NEW: EQViewModel previously would have built its own throwaway
#      `EqualizerService()` instance, disconnected from the singleton
#      MusicService actually wires into the audio pipeline — EQ changes
#      would silently do nothing. Fixed via a new Hilt EntryPoint
#      (di/EqEntryPoint.kt), mirroring the existing LyricsHelperEntryPoint
#      pattern already used elsewhere in this codebase.
# ============================================================================

set -euo pipefail

BRANCH="${BRANCH:-main}"
COMMIT_MSG="${COMMIT_MSG:-Fix EQ ViewModel/MusicService wiring and IconButton default arg}"
DO_PUSH="${DO_PUSH:-1}"   # set to 0 to skip the git push step

say()  { printf '\n\033[1;36m==> %s\033[0m\n' "$1"; }
die()  { printf '\n\033[1;31mERROR: %s\033[0m\n' "$1" >&2; exit 1; }

# ---- 0. sanity checks: must already be inside the repo --------------------
git rev-parse --is-inside-work-tree >/dev/null 2>&1 || die "Not inside a git repo — cd into your Velune checkout first"
[ -d "app/src/main/kotlin/com/nikhil/yt" ] || die "Doesn't look like the Velune repo (expected app/src/main/kotlin/com/nikhil/yt) — check your cwd"

if [ -z "$(git config --global user.email 2>/dev/null)" ] && [ -z "$(git config user.email 2>/dev/null)" ]; then
  die "git identity not set. Run:
  git config --global user.email \"you@example.com\"
  git config --global user.name  \"Your Name\"
then re-run this script."
fi

git diff --quiet && git diff --cached --quiet   || die "Working tree already has uncommitted changes — commit or stash them first"

# ---- 1. write out the combined patch (base64-embedded, decoded to /tmp) ---
PATCH_FILE="$(mktemp /tmp/velune_fix.XXXXXX.patch)"
trap 'rm -f "$PATCH_FILE"' EXIT

base64 -d << 'PATCH_B64_EOF' > "$PATCH_FILE"

PATCH_B64_EOF

# ---- 2. check + apply the patch --------------------------------------------
say "Checking patch applies cleanly"
if git apply --check "$PATCH_FILE" 2>/tmp/velune_patch_check.log; then
  say "Applying patch"
  git apply "$PATCH_FILE"
  PATCH_STATUS="applied"
elif git apply --check --reverse "$PATCH_FILE" 2>/dev/null; then
  say "Patch already applied previously — skipping"
  PATCH_STATUS="already_applied"
else
  say "Patch failed to apply. Details:"
  cat /tmp/velune_patch_check.log >&2
  die "Aborting — no files were changed, nothing will be committed or pushed"
fi

# ---- 3. delete other patch/diff scripts sitting in the repo ---------------
# (only real files tracked in the working tree — never touches $PATCH_FILE,
#  which lives outside the repo in /tmp and is removed by the trap above)
say "Looking for other stray *.patch / *.diff files in the repo to remove"
mapfile -d '' STRAY_PATCHES < <(find . -path ./.git -prune -o   \( -iname '*.patch' -o -iname '*.diff' \) -print0)

if [ "${#STRAY_PATCHES[@]}" -gt 0 ]; then
  for f in "${STRAY_PATCHES[@]}"; do
    say "Removing $f"
    git rm -f -- "$f" >/dev/null 2>&1 || rm -f -- "$f"
  done
else
  say "No stray patch/diff files found in the repo"
fi

# ---- 4. commit + push, only if we actually changed something --------------
if [ "$PATCH_STATUS" = "applied" ] || [ "${#STRAY_PATCHES[@]}" -gt 0 ]; then
  git add -A
  if git diff --cached --quiet; then
    say "Nothing to commit after all — skipping commit/push"
  else
    say "Committing"
    git commit -m "$COMMIT_MSG"

    if [ "$DO_PUSH" = "1" ]; then
      say "Pushing to origin/$BRANCH"
      git push origin "$BRANCH"
    else
      say "DO_PUSH=0 — skipping push (commit is local only)"
    fi
  fi
else
  say "Nothing changed (patch already applied, no stray files) — skipping commit/push"
fi

say "Done."
